from fl_dsl import unit, S, q, concept, math, deeper, src

unit('HOME', 'Mortgages and Homeownership', ['12 Mortgages and Homeownership'])

LE = src('CFPB (Loan Estimate and Closing Disclosure)', 'https://www.consumerfinance.gov/owning-a-home/loan-estimate/', 'Lenders must provide a Loan Estimate within 3 business days of a mortgage application and a Closing Disclosure at least 3 business days before closing.')
PREAPP = src('CFPB', 'https://www.consumerfinance.gov/ask-cfpb/whats-the-difference-between-a-prequalification-letter-and-a-preapproval-letter-en-127/', 'A preapproval is a lender\'s statement of how much it may lend after reviewing documents; it is not a final loan approval.')
ARM = src('CFPB (Adjustable-rate mortgages)', 'https://www.consumerfinance.gov/ask-cfpb/what-is-an-adjustable-rate-mortgage-arm-en-100/', 'An ARM has an initial fixed period, after which the rate adjusts based on an index plus a margin, subject to caps.')

