      q('A $700 payment includes $500 of interest. How much reduces the balance?', '$200',
        [('$700', 'Ignores interest'), ('$500', 'Gives interest'), ('$1,200', 'Adds')],
        intro='Payment − interest = principal reduction.',
        fb='$700 − $500 = $200.', calc=200, sub='Principal reduction'),
      q('After the principal falls, next month\'s interest is…', 'slightly smaller',
        [('slightly larger', 'Reverses'), ('exactly the same', 'Ignores the smaller balance'), ('zero', 'Overstates')],
        intro='Interest is charged on the remaining balance.',
        fb='A smaller balance means less interest.', sub='Pattern'),
      q('An extra $100 paid toward principal does what to future interest?', 'Lowers it',
        [('Raises it', 'Reverses'), ('Has no effect', 'Ignores principal'), ('Doubles it', 'Misreads')],
        fb='Less principal means less interest every month after.', sub='Extra principal'),
      q('Over the life of a fixed-rate mortgage, the monthly principal-and-interest payment…', 'stays the same',
        [('rises every month', 'Misreads'), ('falls every month', 'Confuses interest part with payment'), ('changes with the stock market', 'Confuses mortgages with investments')],
        intro='With a fixed-rate mortgage, the principal-and-interest payment is constant; only the split between interest and principal changes.',
        fb='Fixed-rate P&I stays constant; the mix shifts toward principal.', sub='Fixed payment'),
